-- Tablas de la practica de ingesta incremental.
--
--   stg_lecturas    Area de paso (staging) que recibe las lecturas de cada lote.
--                   Su clave primaria (meter_id, "timestamp") identifica una
--                   lectura de forma unica: es lo que permite escribir por clave
--                   con INSERT ... ON CONFLICT DO NOTHING y que repetir una carga
--                   no duplique filas (idempotencia).
--   estado_ingesta  Una fila por sector con la marca de agua: el ultimo instante
--                   ya cargado (ultima_marca_agua), cuando corrio la ultima carga
--                   (ultima_ejecucion) y cuantas filas trajo (filas_cargadas).
--                   La siguiente carga solo mira lo posterior a esa marca.
--
-- La marca de agua inicial es 2000-01-01, nunca NULL. Con NULL, la condicion
-- "timestamp" > NULL no es verdadera para ninguna fila (el resultado es
-- desconocido), el filtro descarta el lote completo y la primera carga no
-- inserta nada, sin mostrar ningun error.
-- Los nombres de ambas tablas son parte del diseno del pipeline: los
-- componentes siguientes las leen por su nombre exacto.
--
-- Estado inicial: las tablas quedan cargadas con el resultado de la corrida
-- de referencia del Nivel 1 (lote del dia 1, prueba de doble ejecucion y lote
-- del dia 2 con reentregas y tardios): 1200 filas en stg_lecturas y la marca
-- de agua de cada sector en 2024-06-02 23:00:00.

BEGIN;

CREATE TABLE stg_lecturas (
    meter_id VARCHAR,
    "timestamp" TIMESTAMP,
    sector VARCHAR,
    consumo_m3 DOUBLE PRECISION,
    presion_bar DOUBLE PRECISION,
    quality_flag VARCHAR,
    PRIMARY KEY (meter_id, "timestamp")
);


CREATE TABLE estado_ingesta (
    sector VARCHAR PRIMARY KEY,
    ultima_marca_agua TIMESTAMP,
    ultima_ejecucion TIMESTAMP,
    filas_cargadas INTEGER
);



COMMIT;
